def run(self, params, inputs=None):
    """
    params: 节点属性（来自UI）
    inputs: 上游输入（key=输入端口名）
    return: 输出数据（key=输出端口名）
    """
    input_data: list = inputs.input
    return {
        "output": "\n".join(input_data)
    }

